package main

import (
	"context"
	"encoding/json"
	"path/filepath"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/orchestrator"
	"github.com/mellifera/mellifera/internal/store"
)

// watchedDoc builds an item document whose stored ffprobe blob carries a
// format.duration and (optionally) container chapters — the exact stored facts
// the predicate reads (the verbatim ffprobe JSON shape: duration a string,
// chapter boundaries *_time strings, title nested under tags). The doc is
// round-tripped through JSON so it carries the DECODED shape every doc-reading
// closure sees (decodeItemDoc: chapters as []any, numbers as float64).
func watchedDoc(t *testing.T, duration string, chapters ...map[string]any) map[string]any {
	t.Helper()
	format := map[string]any{
		// matroska — the canonical pack case, so the serial_frontier
		// episodes are packable and eligible (h264/aac, 8-bit).
		"format_name": "matroska,webm",
	}
	if duration != "" {
		format["duration"] = duration
	}
	ff := map[string]any{
		"format": format,
		"streams": []any{
			map[string]any{"codec_type": "video", "codec_name": "h264", "pix_fmt": "yuv420p"},
			map[string]any{"codec_type": "audio", "codec_name": "aac"},
		},
	}
	if chapters != nil {
		ff["chapters"] = chapters
	}
	b, err := json.Marshal(map[string]any{"ffprobe": ff})
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	doc := map[string]any{}
	if err := json.Unmarshal(b, &doc); err != nil {
		t.Fatalf("decode doc: %v", err)
	}
	return doc
}

// watchedChapter builds one verbatim-ffprobe-shaped chapter (tags.title,
// start_time/end_time strings) — the muxer shape real files carry.
func watchedChapter(title, start, end string) map[string]any {
	ch := map[string]any{
		"start_time": start,
		"end_time":   end,
		"time_base":  "1/1000",
	}
	if title != "" {
		ch["tags"] = map[string]any{"title": title}
	}
	return ch
}

// TestWatchedSemantics covers the completion-aware watched predicate (design
// D5; spec "Completion-aware watched semantics") at its three joints: the
// pure predicate over stored facts (episodeWatched — the five spec scenarios'
// per-episode judgments), the sweep serial loop's fold into the orchestrator's
// plain Watched map (projectEpisodes + Frontier — which serial fronts and
// which stays skipped), and the eviction recency signal staying
// any-progress-based (watchState over a real store — untouched by the
// predicate).
func TestWatchedSemantics(t *testing.T) {
	t.Run("predicate", func(t *testing.T) {
		for _, tc := range []struct {
			name     string
			doc      map[string]any
			position float64
			want     bool
		}{
			{
				// Reaching the credits start counts watched below the 90% floor.
				name:     "credits_start_counts_below_floor",
				doc:      watchedDoc(t, "1800", watchedChapter("credits", "1500", "1780")),
				position: 1500,
				want:     true,
			},
			{
				name:     "below_credits_start_and_floor_not_watched",
				doc:      watchedDoc(t, "1800", watchedChapter("credits", "1500", "1780")),
				position: 1200,
				want:     false,
			},
			{
				// Ninety percent of a known duration counts watched without credits.
				name:     "ninety_percent_counts_without_credits",
				doc:      watchedDoc(t, "1800"),
				position: 1620,
				want:     true,
			},
			{
				name:     "just_below_ninety_percent_not_watched",
				doc:      watchedDoc(t, "1800"),
				position: 1619.9,
				want:     false,
			},
			{
				// Missing duration AND missing credits is conservative.
				name:     "missing_facts_not_watched",
				doc:      watchedDoc(t, ""),
				position: 1e9,
				want:     false,
			},
			{
				name:     "absent_ffprobe_not_watched",
				doc:      map[string]any{},
				position: 1e9,
				want:     false,
			},
			{
				// Zero position never counts, even with every fact known.
				name:     "zero_position_not_watched",
				doc:      watchedDoc(t, "1800", watchedChapter("credits", "1500", "1780")),
				position: 0,
				want:     false,
			},
			{
				// The lexicon is exact, trimmed, lowercased — Cyrillic included.
				name:     "lexicon_titles_classify",
				doc:      watchedDoc(t, "1800", watchedChapter("Титры", "1500", "1780")),
				position: 1500,
				want:     true,
			},
			{
				name:     "ending_classifies_case_insensitive",
				doc:      watchedDoc(t, "1800", watchedChapter("  Ending ", "1500", "1780")),
				position: 1500,
				want:     true,
			},
			{
				// Substring matching is deliberately absent: "ed" inside
				// "Wedding" must not classify — the 90% rule alone applies.
				name:     "substring_title_never_classifies",
				doc:      watchedDoc(t, "1800", watchedChapter("Wedding", "100", "400")),
				position: 200,
				want:     false,
			},
			{
				// A degenerate (end <= start) range is never a skip range.
				name:     "degenerate_range_not_classified",
				doc:      watchedDoc(t, "1800", watchedChapter("credits", "1500", "1500")),
				position: 1600,
				want:     false,
			},
			{
				// An end-less chapter is never a skip range.
				name: "end_less_chapter_not_classified",
				doc: watchedDoc(t, "1800", map[string]any{
					"start_time": "1500", "time_base": "1/1000",
					"tags": map[string]any{"title": "credits"},
				}),
				position: 1600,
				want:     false,
			},
			{
				// The earliest classified credits start is the threshold.
				name: "earliest_credits_start_is_threshold",
				doc: watchedDoc(t, "1800",
					watchedChapter("ending", "1500", "1780"),
					watchedChapter("ed", "100", "400"),
				),
				position: 100,
				want:     true,
			},
			{
				// The raw-integer boundary form (start × time_base) resolves too.
				name: "raw_integer_boundary_resolves",
				doc: watchedDoc(t, "1800", map[string]any{
					"start": float64(1500000), "end": float64(1780000), "time_base": "1/1000",
					"tags": map[string]any{"title": "credits"},
				}),
				position: 1500,
				want:     true,
			},
		} {
			t.Run(tc.name, func(t *testing.T) {
				if got := episodeWatched(tc.doc, tc.position); got != tc.want {
					t.Errorf("episodeWatched() = %v, want %v", got, tc.want)
				}
			})
		}
	})

	t.Run("serial_frontier", func(t *testing.T) {
		// The fold + Frontier composition, over plain item rows (no store):
		// the watched map the sweep builds must front exactly the serial's
		// first unwatched episode — and skip a fully-watched zero-build
		// serial outright (pack-on-play stays its path).
		ep := func(id, duration string, chapters ...map[string]any) store.Item {
			return store.Item{ID: id, Document: mustJSON(t, watchedDoc(t, duration, chapters...))}
		}

		t.Run("fully_watched_zero_build_stays_skipped", func(t *testing.T) {
			items := []store.Item{
				ep("e1", "1800"),
				ep("e2", "1800", watchedChapter("credits", "1500", "1780")),
				ep("e3", "1800"),
			}
			watched := map[string]bool{}
			eps := projectEpisodes(items, map[string]time.Time{}, false,
				map[string]float64{"e1": 1700, "e2": 1550, "e3": 1620}, watched)
			jobs, fronted := orchestrator.Frontier(orchestrator.FrontierIn{
				Serials: []orchestrator.Serial{{LibraryID: 1, StreamsEnabled: true, Episodes: eps}},
				Watched: watched, Now: time.Now(),
			})
			if len(jobs) != 0 || len(fronted) != 0 {
				t.Errorf("fully watched serial: jobs %v fronted %v, want none (pack-on-play is its path)", jobs, fronted)
			}
		})

		t.Run("mixed_serial_fronts_unwatched_tail", func(t *testing.T) {
			items := []store.Item{
				ep("e1", "1800"),
				ep("e2", "1800", watchedChapter("credits", "1500", "1780")),
				ep("e3", "1800"), // mid-episode, below both thresholds
			}
			watched := map[string]bool{}
			eps := projectEpisodes(items, map[string]time.Time{}, false,
				map[string]float64{"e1": 1700, "e2": 1550, "e3": 300}, watched)
			jobs, fronted := orchestrator.Frontier(orchestrator.FrontierIn{
				Serials: []orchestrator.Serial{{LibraryID: 1, StreamsEnabled: true, Episodes: eps}},
				Watched: watched, Now: time.Now(),
			})
			if len(jobs) != 1 || jobs[0].ItemID != "e3" || jobs[0].Reason != "next-after-watched" {
				t.Errorf("mixed serial jobs = %v, want exactly e3 as next-after-watched", jobs)
			}
			if len(fronted) != 1 || !fronted["e3"] {
				t.Errorf("mixed serial fronted = %v, want exactly e3 (the unwatched tail)", fronted)
			}
		})

		t.Run("any_positive_position_no_longer_watches", func(t *testing.T) {
			// The old signal: 60s into the pilot counted watched and blinded
			// the serial. Under the predicate the pilot fronts.
			items := []store.Item{ep("e1", "1800")}
			watched := map[string]bool{}
			eps := projectEpisodes(items, map[string]time.Time{}, false,
				map[string]float64{"e1": 60}, watched)
			if watched["e1"] {
				t.Fatal("60s of 1800s counted watched — any-position>0 still leaks")
			}
			jobs, fronted := orchestrator.Frontier(orchestrator.FrontierIn{
				Serials: []orchestrator.Serial{{LibraryID: 1, StreamsEnabled: true, Episodes: eps}},
				Watched: watched, Now: time.Now(),
			})
			if len(jobs) != 1 || jobs[0].ItemID != "e1" || jobs[0].Reason != "pilot" || !fronted["e1"] {
				t.Errorf("bare-started serial jobs %v fronted %v, want the pilot fronted", jobs, fronted)
			}
		})
	})

	t.Run("recency_stays_any_progress_based", func(t *testing.T) {
		// watchState over a real store: the positions feed the predicate,
		// the recency stamps (eviction order) are untouched — every positive
		// progress row keeps its stamp regardless of the watched judgment.
		ctx := context.Background()
		st, err := store.Open(ctx, filepath.Join(t.TempDir(), "watched.db"))
		if err != nil {
			t.Fatalf("store.Open: %v", err)
		}
		t.Cleanup(func() { _ = st.Close() })
		libID, err := st.CreateLibrary(ctx, "tv", "/media/watched", "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem := func(id string) {
			t.Helper()
			if err := st.PutItem(ctx, store.Item{
				ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
				RelativePath: id + ".mkv", MediaType: "tv",
				Document: json.RawMessage(`{}`), SchemaVersion: 1,
			}); err != nil {
				t.Fatalf("PutItem %s: %v", id, err)
			}
		}
		putItem("itm_started")
		putItem("itm_midway")
		if _, err := st.PutProgress(ctx, "itm_started", 60); err != nil {
			t.Fatalf("PutProgress started: %v", err)
		}
		if _, err := st.PutProgress(ctx, "itm_midway", 900); err != nil {
			t.Fatalf("PutProgress midway: %v", err)
		}

		positions, recency := watchState(ctx, st)
		if positions["itm_started"] != 60 || positions["itm_midway"] != 900 {
			t.Errorf("positions = %v, want both rows' positions carried", positions)
		}
		if len(recency) != 2 {
			t.Errorf("recency = %v, want a stamp for every progress row (any-progress-based)", recency)
		}
		for id := range recency {
			if recency[id].IsZero() {
				t.Errorf("recency[%s] = zero time, want the parsed RFC3339 stamp", id)
			}
		}
	})
}

// mustJSON marshals v as a store item document.
func mustJSON(t *testing.T, v map[string]any) json.RawMessage {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	return b
}
